using System.Text;

namespace SuffixTree.Esa.Tests.TestSupport;

/// <summary>
/// Deterministic adversarial and random string families (PROGRESS-S1.md, "Test strategy"). Every function is a pure
/// function of its arguments; the randomised ones use <see cref="SplitMix64"/> with the seed passed in, so the same
/// strings can be regenerated by the out-of-repository generators for the libsais vectors.
/// </summary>
public static class StringFamilies
{
    private const string ProteinLetters = "ACDEFGHIKLMNPQRSTVWY";
    private const string DnaLetters = "ACGT";

    /// <summary>
    /// Strictly increasing alphabet of <paramref name="sigma"/> code units: sigma &lt;= 26: 'a'..; sigma &lt;= 0xD000:
    /// U+0100 + i (above 255, below the surrogates); larger: the code units 0..sigma-1.
    /// </summary>
    public static char[] Alphabet(int sigma)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(sigma);
        ArgumentOutOfRangeException.ThrowIfGreaterThan(sigma, 65536);
        var a = new char[sigma];
        for (int i = 0; i < sigma; i++)
            a[i] = sigma <= 26 ? (char)('a' + i) : sigma <= 0xD000 ? (char)(0x100 + i) : (char)i;
        return a;
    }

    /// <summary>The symbol repeated <paramref name="n"/> times.</summary>
    public static string AllSame(int n, char c = 'a') => new(c, n);

    /// <summary>Alternating runs of 'a' and 'b'; each run length is <c>1 + NextInt(maxRun)</c>; the last run is truncated.</summary>
    public static string Runs(int n, int maxRun, ulong seed)
    {
        var rng = new SplitMix64(seed);
        var sb = new StringBuilder(n);
        char c = 'a';
        while (sb.Length < n)
        {
            int len = 1 + rng.NextInt(maxRun);
            sb.Append(c, Math.Min(len, n - sb.Length));
            c = c == 'a' ? 'b' : 'a';
        }
        return sb.ToString();
    }

    /// <summary>A random pattern of length <paramref name="period"/> over 'a'..'d', repeated and truncated to <paramref name="n"/>.</summary>
    public static string Periodic(int n, int period, ulong seed)
    {
        var rng = new SplitMix64(seed);
        var pattern = new char[period];
        for (int i = 0; i < period; i++) pattern[i] = (char)('a' + rng.NextInt(4));
        var c = new char[n];
        for (int i = 0; i < n; i++) c[i] = pattern[i % period];
        return new string(c);
    }

    /// <summary>The primitive pattern a^(p-1) b repeated and truncated to <paramref name="n"/>.</summary>
    public static string PeriodicAaB(int n, int period)
    {
        var c = new char[n];
        for (int i = 0; i < n; i++) c[i] = i % period == period - 1 ? 'b' : 'a';
        return new string(c);
    }

    /// <summary>Fibonacci word: f1 = "a", f2 = "ab", f(k) = f(k-1) f(k-2), truncated to <paramref name="n"/>.</summary>
    public static string Fibonacci(int n)
    {
        string prev = "a", cur = "ab";
        while (cur.Length < n) (prev, cur) = (cur, cur + prev);
        return cur.Substring(0, n);
    }

    /// <summary>Thue-Morse word: t[i] = popcount(i) mod 2, mapped to 'a'/'b'.</summary>
    public static string ThueMorse(int n)
    {
        var c = new char[n];
        for (int i = 0; i < n; i++) c[i] = (char)('a' + (int.PopCount(i) & 1));
        return new string(c);
    }

    /// <summary>
    /// de Bruijn sequence B(k, order) (every word of length <paramref name="order"/> over the first k letters appears exactly
    /// once cyclically) by the Fredricksen-Kessler-Maiorana Lyndon-word construction; optionally truncated to
    /// <paramref name="n"/> characters (n = -1: the full length k^order).
    /// </summary>
    public static string DeBruijn(int k, int order, int n = -1)
    {
        ArgumentOutOfRangeException.ThrowIfLessThan(k, 1);
        ArgumentOutOfRangeException.ThrowIfLessThan(order, 1);
        var a = new int[(k * order) + 1];
        var sb = new StringBuilder();

        void Db(int t, int p)
        {
            if (t > order)
            {
                if (order % p == 0)
                    for (int j = 1; j <= p; j++) sb.Append((char)('a' + a[j]));
                return;
            }
            a[t] = a[t - p];
            Db(t + 1, p);
            for (int j = a[t - p] + 1; j < k; j++)
            {
                a[t] = j;
                Db(t + 1, t);
            }
        }

        Db(1, 1);
        if (n < 0) return sb.ToString();
        ArgumentOutOfRangeException.ThrowIfGreaterThan(n, sb.Length);
        return sb.ToString(0, n);
    }

    /// <summary>(a^k b)* truncated to <paramref name="n"/>.</summary>
    public static string AkB(int n, int k)
    {
        var c = new char[n];
        for (int i = 0; i < n; i++) c[i] = i % (k + 1) == k ? 'b' : 'a';
        return new string(c);
    }

    /// <summary>"abab..." truncated to <paramref name="n"/>: the maximal number of LMS positions (every second position).</summary>
    public static string AbRepeat(int n)
    {
        var c = new char[n];
        for (int i = 0; i < n; i++) c[i] = (i & 1) == 0 ? 'a' : 'b';
        return new string(c);
    }

    /// <summary>Uniform random over <see cref="Alphabet"/>(sigma).</summary>
    public static string Random(int n, int sigma, ulong seed)
    {
        var rng = new SplitMix64(seed);
        var alphabet = Alphabet(sigma);
        var c = new char[n];
        for (int i = 0; i < n; i++) c[i] = alphabet[rng.NextInt(sigma)];
        return new string(c);
    }

    /// <summary>Uniform random over "ACGT".</summary>
    public static string RandomDna(int n, ulong seed) => RandomOver(n, DnaLetters, seed);

    /// <summary>Uniform random over the 20 amino-acid letters.</summary>
    public static string RandomProtein(int n, ulong seed) => RandomOver(n, ProteinLetters, seed);

    /// <summary>Mostly 'a'..'c' with one rare symbol 'z' (probability 1/256).</summary>
    public static string Skewed(int n, ulong seed)
    {
        var rng = new SplitMix64(seed);
        var c = new char[n];
        for (int i = 0; i < n; i++)
            c[i] = rng.NextInt(256) == 0 ? 'z' : (char)('a' + rng.NextInt(3));
        return new string(c);
    }

    /// <summary>A random permutation of the code units 0..n-1 (sigma = n, n &lt;= 65,536).</summary>
    public static string AllDistinct(int n, ulong seed)
    {
        ArgumentOutOfRangeException.ThrowIfGreaterThan(n, 65536);
        var rng = new SplitMix64(seed);
        var c = new char[n];
        for (int i = 0; i < n; i++) c[i] = (char)i;
        for (int i = n - 1; i > 0; i--)
        {
            int j = rng.NextInt(i + 1);
            (c[i], c[j]) = (c[j], c[i]);
        }
        return new string(c);
    }

    /// <summary>BMP characters above 255 and below the surrogate range.</summary>
    public static string Bmp(int n, ulong seed)
    {
        var rng = new SplitMix64(seed);
        var c = new char[n];
        for (int i = 0; i < n; i++) c[i] = (char)(0x100 + rng.NextInt(0xC000));
        return new string(c);
    }

    /// <summary>Valid surrogate pairs drawn from 4 high x 4 low units (a trailing odd unit is 'x').</summary>
    public static string SurrogatePairs(int n, ulong seed)
    {
        var rng = new SplitMix64(seed);
        var c = new char[n];
        for (int i = 0; i + 1 < n; i += 2)
        {
            c[i] = (char)(0xD800 + rng.NextInt(4));
            c[i + 1] = (char)(0xDC00 + rng.NextInt(4));
        }
        if ((n & 1) == 1) c[n - 1] = 'x';
        return new string(c);
    }

    /// <summary>Random units from {U+D800, U+DBFF, U+DC00, U+DFFF, 'a', 'b'}: lone and (rarely) paired surrogates.</summary>
    public static string LoneSurrogates(int n, ulong seed) => RandomOver(n, "\uD800􏰀\uDFFFab", seed);

    /// <summary>Random units from {U+0000, U+FFFF, 'a'}.</summary>
    public static string NulAndFfff(int n, ulong seed) => RandomOver(n, "\0￿a", seed);

    /// <summary>
    /// The complete adversarial list at length <paramref name="n"/> (every text has exactly n code units; all-distinct is
    /// left out when n &gt; 65,536). Names carry the parameters and seed.
    /// </summary>
    public static IEnumerable<(string Name, string Text)> Adversarial(int n, ulong seed)
    {
        yield return ("all-same", AllSame(n));
        foreach (int l in new[] { 2, 16, 256, 65536 })
            yield return ($"runs-L{l}-s{seed}", Runs(n, l, seed));
        foreach (int p in new[] { 2, 3, 5, 7, 64, 65 })
        {
            yield return ($"periodic-p{p}-s{seed}", Periodic(n, p, seed));
            yield return ($"periodic-aab-p{p}", PeriodicAaB(n, p));
        }
        yield return ("fibonacci", Fibonacci(n));
        yield return ("thue-morse", ThueMorse(n));
        yield return ("debruijn-2", DeBruijn(2, SmallestOrder(2, n), n));
        yield return ("debruijn-4", DeBruijn(4, SmallestOrder(4, n), n));
        foreach (int k in new[] { 1, 7, 100 })
            yield return ($"akb-k{k}", AkB(n, k));
        yield return ($"random-binary-s{seed}", Random(n, 2, seed));
        yield return ($"random-dna-s{seed}", RandomDna(n, seed));
        yield return ($"random-protein-s{seed}", RandomProtein(n, seed));
        foreach (int sigma in new[] { 3, 20, 256, 1000 })
            yield return ($"random-sigma{sigma}-s{seed}", Random(n, sigma, seed));
        yield return ($"skewed-s{seed}", Skewed(n, seed));
        if (n <= 65536) yield return ($"all-distinct-s{seed}", AllDistinct(n, seed));
        yield return ($"bmp-s{seed}", Bmp(n, seed));
        yield return ($"surrogate-pairs-s{seed}", SurrogatePairs(n, seed));
        yield return ($"lone-surrogates-s{seed}", LoneSurrogates(n, seed));
        yield return ($"nul-ffff-s{seed}", NulAndFfff(n, seed));
        yield return ("ab-repeat", AbRepeat(n));
    }

    private static int SmallestOrder(int k, int n)
    {
        int order = 1;
        long size = k;
        while (size < n)
        {
            size *= k;
            order++;
        }
        return order;
    }

    private static string RandomOver(int n, string letters, ulong seed)
    {
        var rng = new SplitMix64(seed);
        var c = new char[n];
        for (int i = 0; i < n; i++) c[i] = letters[rng.NextInt(letters.Length)];
        return new string(c);
    }
}
